action_details.action_postfix:
// Physical nexus established - filing required
true result.ky_has_nexus xdef
"Kentucky filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.ky_has_nexus xdef
"Kentucky filing required: Economic nexus (exceeds $100,000 gross receipts or 200 transactions)" job.audit_trail swap addto

// Calculate Kentucky state additions
0.0 /ky_additions xdef

// Common Kentucky additions:
// - Federal interest income
// - IRC 199A addback
// - State tax refunds

result.ky_us_interest_income 0.0 ne
{
  ky_additions result.ky_us_interest_income add /ky_additions xdef
} if

ky_additions result.ky_state_additions xdef

// Calculate Kentucky state subtractions
0.0 /ky_subtractions xdef

// Common Kentucky subtractions:
// - KY municipal bond interest
// - Dividends from KY corporations

result.ky_municipal_interest 0.0 ne
{
  ky_subtractions result.ky_municipal_interest add /ky_subtractions xdef
} if

result.ky_dividends_from_ky_corps 0.0 ne
{
  ky_subtractions result.ky_dividends_from_ky_corps add /ky_subtractions xdef
} if

ky_subtractions result.ky_state_subtractions xdef

"Kentucky additions: $" result.ky_state_additions cvs strconcat ", subtractions: $" strconcat result.ky_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Kentucky taxable income // Federal taxable income apportioned to KY + additions - subtractions result.ky_apportioned_income result.ky_state_additions add result.ky_state_subtractions sub 0.0 max result.ky_taxable_income xdef
// Calculate Kentucky tax using flat rate: 4.5% result.ky_taxable_income result.ky_corp_tax_rate mul /ky_tax_before_credits xdef
// Subtract Kentucky state credits ky_tax_before_credits result.ky_state_credits sub 0.0 max result.ky_tax_liability xdef
// Calculate refund or amount owed result.ky_estimated_payments result.ky_tax_liability sub result.ky_refund_or_owed xdef
"Kentucky taxable income: $" result.ky_taxable_income cvs strconcat job.audit_trail swap addto "Kentucky tax liability (4.5%): $" result.ky_tax_liability cvs strconcat job.audit_trail swap addto
